#!/usr/bin/env python3
"""
Solver with destination-based clustering
Strategy: For each destination, concentrate shipments on 1-2 primary warehouses
"""

import json
from collections import defaultdict
from pathlib import Path

def load_data(input_dir):
    shipments = {}
    with open(input_dir / "shipments.jsonl") as f:
        for line in f:
            shipments[json.loads(line)["shipment_id"]] = json.loads(line)

    warehouses = {}
    with open(input_dir / "warehouses.jsonl") as f:
        for line in f:
            warehouses[json.loads(line)["warehouse_id"]] = json.loads(line)

    destinations = {}
    with open(input_dir / "destinations.jsonl") as f:
        for line in f:
            destinations[json.loads(line)["destination_id"]] = json.loads(line)

    routes = {}
    routes_by_wh_dest = {}
    with open(input_dir / "routes.jsonl") as f:
        for line in f:
            r = json.loads(line)
            routes[r["route_id"]] = r
            routes_by_wh_dest[(r["warehouse_id"], r["destination_id"])] = r

    return shipments, warehouses, destinations, routes_by_wh_dest

def main():
    shipments, warehouses, destinations, routes_by_wh_dest = load_data(Path("/app/task_file/input_data"))

    shipment_ids = list(shipments.keys())
    n = len(shipments)

    # Group shipments by destination
    shipments_by_dest = defaultdict(list)
    for sid in shipment_ids:
        shipments_by_dest[shipments[sid]["destination_id"]].append(sid)

    print(f"Destinations with shipments: {len(shipments_by_dest)}")
    for did, sids in shipments_by_dest.items():
        print(f"  Dest {did}: {len(sids)} shipments")

    # For each destination, find all valid warehouses (capability + time constraints)
    dest_to_valid_whs = {}
    for did, sids in shipments_by_dest.items():
        valid_whs = []
        dest = destinations[did]
        for sid in sids:
            s = shipments[sid]
            for wh_id, wh in warehouses.items():
                # Capability check
                if s["requires_hazmat"] and not wh["handles_hazmat"]:
                    continue
                if s["requires_refrigerated"] and not wh["handles_refrigerated"]:
                    continue
                if s["requires_oversized"] and not wh["handles_oversized"]:
                    continue

                rk = (wh_id, did)
                if rk not in routes_by_wh_dest:
                    continue

                route = routes_by_wh_dest[rk]
                if s["requires_hazmat"] and not route["allows_hazmat"]:
                    continue
                if s["requires_refrigerated"] and not route["allows_refrigerated"]:
                    continue
                if s["requires_oversized"] and not route["allows_oversized"]:
                    continue

                # Time check (must work for ALL shipments to this dest from this wh)
                arrival = wh["availability_start"] + route["transit_time_hours"]
                if arrival > s["deadline_hours"]:
                    continue
                if arrival < dest["delivery_window_start"] or arrival > dest["delivery_window_end"]:
                    continue

                valid_whs.append((wh_id, route))

        # Keep only warehouses that can handle at least one shipment
        dest_to_valid_whs[did] = list(set(valid_whs))  # Deduplicate

    # Select primary warehouses for each destination (prefer hubs, low cost)
    primary_wh_by_dest = {}
    for did, valid_whs in dest_to_valid_whs.items():
        # Score each warehouse: prefer hubs, lower cost, good time windows
        scored = []
        for wh_id, route in valid_whs:
            wh = warehouses[wh_id]
            # Base score: hub preference
            score = 0.0
            if wh["is_hub"]:
                score -= 0.5  # Strong hub preference
            # Cost
            handling = wh["base_handling_cost"] * 100 / 100.0  # avg volume
            transport = route["base_cost_per_km"] * route["distance_km"] * 500 / 1000.0  # avg weight
            score -= (handling + transport)
            # Transit time (lower is better)
            score -= route["transit_time_hours"]
            scored.append((score, wh_id, route))

        # Sort by score (best first)
        scored.sort(key=lambda x: x[0])
        # Pick top 2-3 warehouses
        primary_wh_by_dest[did] = [x[1] for x in scored[:3]]

    print(f"Primary warehouses selected for {len(primary_wh_by_dest)} destinations")

    # State tracking
    assignment = {}
    wh_volume = defaultdict(int)
    wh_weight = defaultdict(int)
    route_volume = defaultdict(int)
    route_weight = defaultdict(int)
    region_count = defaultdict(int)

    wh_vol_cap = {wid: w["volume_capacity"] for wid, w in warehouses.items()}
    wh_wgt_cap = {wid: w["weight_capacity"] for wid, w in warehouses.items()}
    wh_min_batch = {wid: w["min_batch_volume"] for wid, w in warehouses.items()}
    route_vol_cap = {k: v["capacity_volume"] for k, v in routes_by_wh_dest.items()}
    route_wgt_cap = {k: v["capacity_weight"] for k, v in routes_by_wh_dest.items()}

    def try_assign(sid, wh_id, route):
        s = shipments[sid]
        dest_id = route["destination_id"]

        if wh_volume[wh_id] + s["volume"] > wh_vol_cap[wh_id]:
            return False
        if wh_weight[wh_id] + s["weight"] > wh_wgt_cap[wh_id]:
            return False

        rk = (wh_id, dest_id)
        if route_volume[rk] + s["volume"] > route_vol_cap[rk]:
            return False
        if route_weight[rk] + s["weight"] > route_wgt_cap[rk]:
            return False

        assignment[sid] = (wh_id, dest_id)
        wh_volume[wh_id] += s["volume"]
        wh_weight[wh_id] += s["weight"]
        route_volume[rk] += s["volume"]
        route_weight[rk] += s["weight"]
        region_count[destinations[dest_id]["region"]] += 1
        return True

    def undo_assign(sid):
        wh_id, dest_id = assignment.get(sid)
        if wh_id is None:
            return
        s = shipments[sid]
        del assignment[sid]
        wh_volume[wh_id] -= s["volume"]
        wh_weight[wh_id] -= s["weight"]
        rk = (wh_id, dest_id)
        route_volume[rk] -= s["volume"]
        route_weight[rk] -= s["weight"]
        region_count[destinations[dest_id]["region"]] -= 1

    # Assign: for each shipment, try primary warehouse for its destination first
    # If fails, try alternatives
    for sid in shipment_ids:
        s = shipments[sid]
        did = s["destination_id"]
        primary_whs = primary_wh_by_dest.get(did, [])

        assigned = False
        for wh_id in primary_whs:
            # Find the route
            rk = (wh_id, did)
            if rk in routes_by_wh_dest:
                route = routes_by_wh_dest[rk]
                if try_assign(sid, wh_id, route):
                    assigned = True
                    break

        if not assigned:
            # Try all valid warehouses as fallback
            for wh_id, route in dest_to_valid_whs.get(did, []):
                if try_assign(sid, wh_id, route):
                    break

    if len(assignment) != n:
        print(f"Failed: only {len(assignment)}/{n} assigned")
        return 1

    print(f"Successfully assigned all {n} shipments")

    # Write output
    output_file = Path("/app/task_file/output_data/assignments.jsonl")
    output_file.parent.mkdir(parents=True, exist_ok=True)
    with open(output_file, 'w') as f:
        for sid in sorted(assignment.keys()):
            wh_id, dest_id = assignment[sid]
            f.write(json.dumps({"shipment_id": sid, "warehouse_id": wh_id, "destination_id": dest_id}) + '\n')

    print("Done")
    return 0

if __name__ == "__main__":
    exit(main())
